// Mode Switcher - updates the active_mode in hoggle-behavior-modes.json
const fs = require('fs');
const modesPath = '/data/crystals/personality/hoggle-behavior-modes.json';

// Get the requested mode from the webhook body
const requestedMode = ($input.item.json.body.mode || '').toLowerCase().trim();

// Valid modes
const validModes = ['classroom', 'demo', 'district', 'hype', 'gaming'];

if (!requestedMode) {
  return { json: { success: false, error: 'No mode specified. Send {"mode": "classroom|demo|district|hype|gaming"}' } };
}

if (!validModes.includes(requestedMode)) {
  return { json: { success: false, error: `Invalid mode: ${requestedMode}. Valid modes: ${validModes.join(', ')}` } };
}

// Read current file
let modesData;
try {
  modesData = JSON.parse(fs.readFileSync(modesPath, 'utf8'));
} catch (err) {
  return { json: { success: false, error: 'Could not read behavior modes crystal: ' + err.message } };
}

const previousMode = modesData.data.active_mode;

// Update the active mode
modesData.data.active_mode = requestedMode;
modesData.updated = new Date().toISOString().split('T')[0];

// Write back
try {
  fs.writeFileSync(modesPath, JSON.stringify(modesData, null, 2), 'utf8');
} catch (err) {
  return { json: { success: false, error: 'Could not write behavior modes crystal: ' + err.message } };
}

// Also update emotional state if gaming mode (banished)
if (requestedMode === 'gaming') {
  try {
    const emotionalPath = '/data/crystals/personality/hoggle-emotional-state.json';
    const emotionalData = JSON.parse(fs.readFileSync(emotionalPath, 'utf8'));
    emotionalData.data.current_mood = 'grumpy_post_banish';
    emotionalData.data.energy = 2;
    emotionalData.updated = new Date().toISOString().split('T')[0];
    fs.writeFileSync(emotionalPath, JSON.stringify(emotionalData, null, 2), 'utf8');
  } catch (err) {
    // Non-critical, continue
  }
}

// If coming back from gaming, set mood to grumpy then cheerful
if (previousMode === 'gaming' && requestedMode === 'classroom') {
  try {
    const emotionalPath = '/data/crystals/personality/hoggle-emotional-state.json';
    const emotionalData = JSON.parse(fs.readFileSync(emotionalPath, 'utf8'));
    emotionalData.data.current_mood = 'grumpy_post_banish';
    emotionalData.data.energy = 5;
    emotionalData.updated = new Date().toISOString().split('T')[0];
    fs.writeFileSync(emotionalPath, JSON.stringify(emotionalData, null, 2), 'utf8');
  } catch (err) {
    // Non-critical
  }
}

return {
  json: {
    success: true,
    previous_mode: previousMode,
    new_mode: requestedMode,
    message: `Hoggle switched from ${previousMode} to ${requestedMode} mode`
  }
};
